<template>
  <div class="slider-wrapper">
    <div style="height: 600px; max-height: 85vh; position: relative;">
      <!-- Swiper con datos dinámicos de la BD -->
      <swiper v-if="slidersDinamicos && slidersDinamicos.length > 0" :options="swiperOptionTop" class="gallery-top" ref="swiperTop">
        <swiper-slide 
          v-for="slide in slidersDinamicos" 
          :key="slide.id" 
          class="dynamic-slide"
        >
          <!-- Imagen de fondo -->
          <div class="slide-bg" :style="{ backgroundImage: 'url(' + getImagenUrl(slide.imagen) + ')' }"></div>
          
          <!-- Capa de oscurecimiento u overlay para legibilidad -->
          <div class="slide-overlay-mask"></div>

          <!-- Contenido textual y botón CTA -->
          <div v-if="slide.titulo || slide.subtitulo || slide.texto_boton" class="slide-overlay-content">
            <h2 v-if="slide.titulo" class="slide-title">{{ slide.titulo }}</h2>
            <p v-if="slide.subtitulo" class="slide-subtitle">{{ slide.subtitulo }}</p>
            <a v-if="slide.texto_boton" :href="slide.url_boton || '#'" class="btn btn-primary slide-btn">
              {{ slide.texto_boton }} <i class="fa fa-arrow-right ml-1"></i>
            </a>
          </div>
        </swiper-slide>
        
        <div class="swiper-button-next swiper-button-white" slot="button-next"></div>
        <div class="swiper-button-prev swiper-button-white" slot="button-prev"></div>
      </swiper>

      <!-- Fallback estático en caso de no haber sliders en BD -->
      <swiper v-else :options="swiperOptionTop" class="gallery-top" ref="swiperTop">
        <swiper-slide class="slide-1"></swiper-slide>
        <swiper-slide class="slide-2"></swiper-slide>
        
        <div class="swiper-button-next swiper-button-white" slot="button-next"></div>
        <div class="swiper-button-prev swiper-button-white" slot="button-prev"></div>
      </swiper>
    </div>
  </div>
</template>

<script>
import 'swiper/swiper-bundle.css'
import { swiper, swiperSlide } from 'vue-awesome-swiper'
import axios from 'axios'

export default {
  components: {
    swiper,
    swiperSlide
  },
  name: 'slider',
  data() {
    return {
      slidersDinamicos: [],
      swiperOptionTop: {
        spaceBetween: 0,
        loop: true,
        autoplay: {
          delay: 5000,
          disableOnInteraction: false
        },
        navigation: {
          nextEl: '.swiper-button-next',
          prevEl: '.swiper-button-prev'
        }
      }
    }
  },
  methods: {
    cargarSlidersPublicos() {
      let me = this;
      let origin = (typeof window !== 'undefined' && window.location.origin) ? window.location.origin : '';
      let url = origin + '/slider/publicos?ubicacion=principal';

      axios.get(url).then(response => {
        if (response.data && response.data.length > 0) {
          me.slidersDinamicos = response.data;
        }
      }).catch(err => {
        console.log("Cargando sliders estáticos por defecto", err);
      });
    },
    getImagenUrl(path) {
      if (!path) return '';
      if (path.startsWith('http://') || path.startsWith('https://')) return path;
      let cleanPath = path.startsWith('/') ? path : '/' + path;
      let origin = (typeof window !== 'undefined' && window.location.origin) ? window.location.origin : '';
      return origin + cleanPath;
    }
  },
  created() {
    this.cargarSlidersPublicos();
  }
}
</script>

