                        <img :src="`${dominio}/img/productos/${producto.imagenes[0].nombre}`" 
                             class="img-fluid rounded-25 shadow-sm main-img" alt="Producto">
                    </div>
                    <div class="thumbnails-row d-flex gap-3 px-4 pb-4 overflow-auto">
                        <div v-for="(img, index) in producto.imagenes" :key="index" 
                             class="thumb-box-premium" :class="{'active': index === 0}">
                            <img :src="`${dominio}/img/productos/${img.nombre}`" class="img-fluid rounded-10">
                        </div>
                    </div>
                </div>

                <!-- Right: Product Config -->
                <div class="col-lg-6 p-4 p-md-5 bg-white border-start">
