                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><router-link to="/tienda">Tienda</router-link></li>
                            <li class="breadcrumb-item active">{{producto.nombre}}</li>
                        </ol>
                    </nav>

                    <h1 class="product-title-premium text-brand-purple mb-2">{{producto.nombre}}</h1>
