</template>

<script>
import { mapState } from 'vuex'
import axios from 'axios'

export default {
    name: 'ProductoView',
    data() {
        return {
            producto: null,
            cantidad: 100,
            atributosTienda: {},
            specsSeleccionadas: {
                'Tinta': '',
                'Papel': '',
                'Acabado': '',
                'Terminado': ''
            },
            matchFound: false,
            cotizacionMensaje: '',
            detallesCalculo: null
        }
    },
    computed: {
        ...mapState(['dominio', 'products'])
    },
    methods: {
        fetchProduct() {
            const id = this.$route.params.id;
            // Intentar buscar en el store primero
            let list = this.products.data || this.products;
            if (Array.isArray(list)) {
                this.producto = list.find(p => p.id == id);
            }
            
            // Si no está en el store (acceso directo), cargarlo vía API (mocked for now as we use store)
            if (!this.producto) {
                // ... lógica de fetch API
            }
        },
        getAtributosTienda() {
            axios.get(this.dominio + '/api/tienda/atributos').then(response => {
                this.atributosTienda = response.data;
            });
        },
        cotizarPrecio() {
            if (!this.producto) return;
            let especificaciones = Object.keys(this.specsSeleccionadas).map(key => ({
                titulo: key,
                valor: this.specsSeleccionadas[key]
            })).filter(s => s.valor);

            axios.post(this.dominio + '/api/tienda/cotizar', {
                articulo_id: this.producto.id,
                cantidad: this.cantidad,
                especificaciones: especificaciones
            }).then(response => {
                this.producto.valor_total = response.data.total;
                if (response.data.match_found) {
                    this.matchFound = true;
                    this.cotizacionMensaje = '';
                    this.detallesCalculo = null;
                } else {
                    this.matchFound = false;
                    this.cotizacionMensaje = response.data.mensaje;
                    this.detallesCalculo = response.data.detalles_calculo;
                }
            });
        },
        addToCart() {
            // Lógica de agregar al carrito
            this.$store.commit('saveToCart', this.producto, this.cantidad);
            this.$router.push('/checkout');
        }
    },
    created() {
        this.fetchProduct();
        this.getAtributosTienda();
    }
}
</script>

