          <div class="circle-avatar rounded-circle overflow-hidden mb-2 bg-white d-flex align-items-center justify-content-center" style="margin: 0 auto; border: 1.5px solid #1a1a1a;">
            <img v-if="categoria.imagen" :src="`${dominio}/img/categorias/${categoria.imagen}`" class="img-fluid object-fit-cover w-100 h-100" />
            <div v-else class="w-100 h-100 d-flex align-items-center justify-content-center bg-light">
