<script>

import { swiper, swiperSlide } from 'vue-awesome-swiper'
import { mapState } from 'vuex'

  export default {
    data() {
      return {
        swiperOption: {
          slidesPerView: 3,
          spaceBetween: 20,
          pagination: {
            el: '.swiper-pagination',
            clickable: true
          }
        },
        dominio: this.$store.state.dominio
      }
    },
    methods: {
    handleResize() {
      if(window.innerWidth < 580){
        this.swiperOption.slidesPerView = 2
      }else {
        this.swiperOption.slidesPerView = 3
      }
     },
     filtrarCategoria(id) {
       this.$store.dispatch('getProductosCat', id)
       this.$router.push('/tienda/' + id)
     }
    },
    beforeCreate(){
        
    },
    computed: {
      ...mapState(['featuredProducts', 'categories'])
    }
  }
</script>

